   941  int hts_parse_opt_list(htsFormat *fmt, const char *str) {
   942      while (str && *str) {
   943          const char *str_start;
   944          int len;
   945          char arg[8001];
   946
   947          while (*str && *str == ',')
   948              str++;
   949
   950          for (str_start = str; *str && *str != ','; str++);
   951          len = str - str_start;
   952
   953          // Produce a nul terminated copy of the option
   954          strncpy(arg, str_start, len < 8000 ? len : 8000);
   955          arg[len < 8000 ? len : 8000] = '\0';
   956
   957          if (hts_opt_add((hts_opt **)&fmt->specific, arg) != 0)
   958              return -1;
   959
   960          if (*str)
   961              str++;
   962      }
   963
   964      return 0;
   965  }
